/**
 * @file academyCoursesSnapshot.ts
 */

import type { GameRuntime } from '../types/game.js';
import {
    ACADEMY_COURSES,
    ACADEMY_COURSE_IDS,
    type AcademyCourseId,
} from '../../constants/balance/academyCourses.ts';
import { getAcademyCourseEntry, getNextAcademyRankCost } from './academyCourses.ts';
import { publish } from '../bus/pub.js';
import { GameEventType as Evt } from '../bus/events.js';

export interface AcademyCourseCardSnapshot {
    id: AcademyCourseId;
    nameKey: string;
    spriteKey: string;
    courseType: string | null;
    rank: number;
    credits: number;
    nextCost: number | null;
    canInvest: boolean;
    locked: boolean;
}

export interface AcademyCoursesSnapshot {
    language: string;
    titleLabel: string;
    creditsLabel: string;
    rankLabel: string;
    investLabel: string;
    lockedLabel: string;
    courses: AcademyCourseCardSnapshot[];
}

function t(game: GameRuntime, key: string, fallback: string): string {
    if (typeof game.t !== 'function') return fallback;
    const got = game.t(key);
    return got && got !== key ? got : fallback;
}

export function buildAcademyCoursesSnapshot(game: GameRuntime): AcademyCoursesSnapshot {
    const courses: AcademyCourseCardSnapshot[] = [];
    for (const id of ACADEMY_COURSE_IDS) {
        const def = ACADEMY_COURSES[id];
        const entry = getAcademyCourseEntry(game, id);
        const nextCost = getNextAcademyRankCost(game, id);
        const locked = entry.rank < 1;
        courses.push({
            id,
            nameKey: def.nameKey,
            spriteKey: def.spriteKey,
            courseType: def.courseType,
            rank: entry.rank,
            credits: entry.credits,
            nextCost,
            canInvest: !locked && nextCost != null && entry.credits >= nextCost,
            locked,
        });
    }
    return {
        language: String(game.language ?? 'fr'),
        titleLabel: t(game, 'academy.title', 'Cours de l\'Académie'),
        creditsLabel: t(game, 'academy.credits', 'Crédits'),
        rankLabel: t(game, 'academy.rank', 'Rang'),
        investLabel: t(game, 'academy.invest', 'Investir'),
        lockedLabel: t(game, 'academy.locked', 'Verrouillé'),
        courses,
    };
}

export function notifyAcademyCoursesChanged(game: GameRuntime): void {
    publish(Evt.ACADEMY_COURSES_CHANGED, { game });
}
