import { TYPES } from '../core.ts';

export type AcademyCourseId =
    | 'founder'
    | 'bug'
    | 'flora'
    | 'bolt'
    | 'kite'
    | 'plain'
    | 'spook'
    | 'dark'
    | 'freeze';

export interface AcademyRankDef {
    rank: number;
    creditCost: number;
    effect: string;
    value: number;
    /** When set, bonus applies only to actions of this type. */
    typeFilter?: string;
}

export interface AcademyCourseDef {
    id: AcademyCourseId;
    badgeKey: string | null;
    courseType: string | null;
    spriteKey: string;
    nameKey: string;
    ranks: AcademyRankDef[];
}

