/** Paldea gym badge keys mapped to academy course ids. */
export const PALDEA_BADGE_TO_ACADEMY_COURSE: Record<string, AcademyCourseId> = {
    bug: 'bug',
    flora: 'flora',
    bolt: 'bolt',
    kite: 'kite',
    plain: 'plain',
    spook: 'spook',
    dark: 'dark',
    freeze: 'freeze',
};

function typedDamageRanks(courseType: string, extraDamage = 0.03): AcademyRankDef[] {
    return [
        { rank: 1, creditCost: 0, effect: 'account_talent', value: 0 },
        { rank: 2, creditCost: ACADEMY_RANK_CREDIT_COSTS[2], effect: 'damage_mult', value: extraDamage, typeFilter: courseType },
        { rank: 3, creditCost: ACADEMY_RANK_CREDIT_COSTS[3], effect: 'capture_chance', value: 0.05, typeFilter: courseType },
        { rank: 4, creditCost: ACADEMY_RANK_CREDIT_COSTS[4], effect: 'crit_chance', value: 0.01, typeFilter: courseType },
        { rank: 5, creditCost: ACADEMY_RANK_CREDIT_COSTS[5], effect: 'damage_mult', value: 0.08, typeFilter: courseType },
    ];
}

