/**
 * @file academyCourses.ts
 * Paldea Academy Courses — type mastery per gym badge.
 */

import {
    ACADEMY_ARENA_QUEST_CREDIT_BONUS,
    ACADEMY_COURSES,
    ACADEMY_COURSE_IDS,
    ACADEMY_SUBWAY_TYPE_CREDIT_BONUS,
    ACADEMY_TYPED_WINS_PER_CREDIT,
    ACADEMY_TYPE_HUNT_CREDIT_BONUS,
    ACADEMY_ADVANCED_HUB_CREDITS_SPENT,
    PALDEA_BADGE_TO_ACADEMY_COURSE,
    type AcademyCourseId,
} from '../../constants/balance/academyCourses.ts';
import type { GameRuntime } from '../types/game.js';

export interface AcademyCourseEntry {
    rank: number;
    credits: number;
    creditsSpent: number;
    typedWinsTowardCredit: number;
}

export type AcademyCoursesState = Record<AcademyCourseId, AcademyCourseEntry>;

function emptyEntry(): AcademyCourseEntry {
    return { rank: 0, credits: 0, creditsSpent: 0, typedWinsTowardCredit: 0 };
}

export function createDefaultAcademyCourses(): AcademyCoursesState {
    const out = {} as AcademyCoursesState;
    for (const id of ACADEMY_COURSE_IDS) {
        out[id] = emptyEntry();
    }
    return out;
}

export function normalizeAcademyCourses(raw: unknown): AcademyCoursesState {
    const base = createDefaultAcademyCourses();
    if (!raw || typeof raw !== 'object') return base;
    const o = raw as Record<string, unknown>;
    for (const id of ACADEMY_COURSE_IDS) {
        const entry = o[id];
        if (!entry || typeof entry !== 'object') continue;
        const e = entry as Record<string, unknown>;
        base[id] = {
            rank: Math.max(0, Math.min(5, Math.floor(Number(e.rank) || 0))),
            credits: Math.max(0, Math.floor(Number(e.credits) || 0)),
            creditsSpent: Math.max(0, Math.floor(Number(e.creditsSpent) || 0)),
            typedWinsTowardCredit: Math.max(0, Math.floor(Number(e.typedWinsTowardCredit) || 0)),
        };
    }
    return base;
}

export function getAcademyCoursesState(game: GameRuntime): AcademyCoursesState {
    if (!game.academyCourses || typeof game.academyCourses !== 'object') {
        game.academyCourses = createDefaultAcademyCourses();
    }
    return game.academyCourses as AcademyCoursesState;
}

export function getAcademyCourseEntry(game: GameRuntime, courseId: AcademyCourseId): AcademyCourseEntry {
    return getAcademyCoursesState(game)[courseId];
}

export function unlockAcademyCourse(game: GameRuntime, courseId: AcademyCourseId, rank = 1): void {
    const entry = getAcademyCourseEntry(game, courseId);
    if (entry.rank < rank) entry.rank = rank;
}

export function grantAcademyCredits(game: GameRuntime, courseId: AcademyCourseId, amount: number): void {
    if (amount <= 0) return;
    const entry = getAcademyCourseEntry(game, courseId);
    entry.credits += Math.floor(amount);
}

function courseIdForType(type: string): AcademyCourseId | null {
    for (const id of ACADEMY_COURSE_IDS) {
        if (id === 'founder') continue;
        const def = ACADEMY_COURSES[id];
        if (def.courseType === type) return id;
    }
    return null;
}

export function onPaldeaRegionVisited(game: GameRuntime): void {
    unlockAcademyCourse(game, 'founder', 1);
}

export function onPaldeaGymBadgeWon(game: GameRuntime, badgeKey: string): void {
    const courseId = PALDEA_BADGE_TO_ACADEMY_COURSE[badgeKey];
    if (!courseId) return;
    unlockAcademyCourse(game, courseId, 1);
    grantAcademyCredits(game, courseId, ACADEMY_ARENA_QUEST_CREDIT_BONUS);
}

export function onPaldeaTypedZoneWin(game: GameRuntime, pokemonType: string | null | undefined): void {
    if (!pokemonType) return;
    const zone = game.currentZone;
    if (!zone || zone.regionId !== 'paldea') return;
    const courseId = courseIdForType(pokemonType);
    if (!courseId) return;
    const entry = getAcademyCourseEntry(game, courseId);
    if (entry.rank < 1) return;
    entry.typedWinsTowardCredit += 1;
    if (entry.typedWinsTowardCredit >= ACADEMY_TYPED_WINS_PER_CREDIT) {
        entry.typedWinsTowardCredit = 0;
        entry.credits += 1;
    }
}

export function onAcademyTypeHuntCompleted(game: GameRuntime, requiredType: string): void {
    const courseId = courseIdForType(requiredType);
    if (!courseId) return;
    const entry = getAcademyCourseEntry(game, courseId);
    if (entry.rank < 1) return;
    grantAcademyCredits(game, courseId, ACADEMY_TYPE_HUNT_CREDIT_BONUS);
}

export function onAcademySubwayWin(game: GameRuntime): void {
    const team = game.playerTeam ?? [];
    if (team.length === 0) return;
    const typeCounts = new Map<string, number>();
    for (const c of team) {
        const t = String(c.type ?? '');
        typeCounts.set(t, (typeCounts.get(t) ?? 0) + 1);
    }
    let bestType = '';
    let bestCount = 0;
    for (const [t, n] of typeCounts) {
        if (n > bestCount) {
            bestCount = n;
            bestType = t;
        }
    }
    if (bestCount < Math.ceil(team.length / 2)) return;
    const courseId = courseIdForType(bestType);
    if (!courseId) return;
    const entry = getAcademyCourseEntry(game, courseId);
    if (entry.rank < 1) return;
    grantAcademyCredits(game, courseId, ACADEMY_SUBWAY_TYPE_CREDIT_BONUS);
}

export function getNextAcademyRankCost(game: GameRuntime, courseId: AcademyCourseId): number | null {
    const entry = getAcademyCourseEntry(game, courseId);
    const nextRank = entry.rank + 1;
    if (nextRank > 5) return null;
    const def = ACADEMY_COURSES[courseId];
    const rankDef = def.ranks.find((r) => r.rank === nextRank);
    return rankDef?.creditCost ?? null;
}

export function canInvestAcademyCourse(game: GameRuntime, courseId: AcademyCourseId): boolean {
    const entry = getAcademyCourseEntry(game, courseId);
    if (entry.rank < 1) return false;
    const cost = getNextAcademyRankCost(game, courseId);
    if (cost == null) return false;
    return entry.credits >= cost;
}

export function investAcademyCourse(game: GameRuntime, courseId: AcademyCourseId): boolean {
    const entry = getAcademyCourseEntry(game, courseId);
    if (entry.rank < 1) return false;
    const nextRank = entry.rank + 1;
    if (nextRank > 5) return false;
    const cost = getNextAcademyRankCost(game, courseId);
    if (cost == null || entry.credits < cost) return false;
    entry.credits -= cost;
    entry.creditsSpent += cost;
    entry.rank = nextRank;
    if (typeof game.checkSpecialQuests === 'function') {
        game.checkSpecialQuests('academy_course_rank', { courseId, rank: nextRank });
    }
    return true;
}

export function getAcademyCourseBonus(
    game: GameRuntime,
    effectType: string,
    actionType?: string | null,
): number {
    let total = 0;
    const state = getAcademyCoursesState(game);
    for (const id of ACADEMY_COURSE_IDS) {
        const entry = state[id];
        if (entry.rank < 2) continue;
        const def = ACADEMY_COURSES[id];
        for (const rankDef of def.ranks) {
            if (rankDef.rank > entry.rank || rankDef.rank < 2) continue;
            if (rankDef.effect === 'account_talent') continue;
            if (rankDef.effect !== effectType) continue;
            if (rankDef.typeFilter && actionType && rankDef.typeFilter !== actionType) continue;
            if (rankDef.typeFilter && !actionType) continue;
            total += Number(rankDef.value) || 0;
        }
    }
    return total;
}

export function getAcademyPaldeaXpMult(game: GameRuntime): number {
    const entry = getAcademyCourseEntry(game, 'founder');
    if (entry.rank < 1) return 0;
    let mult = 0;
    const def = ACADEMY_COURSES.founder;
    for (const rankDef of def.ranks) {
        if (rankDef.rank > entry.rank) continue;
        if (rankDef.effect === 'paldea_xp_mult') mult += rankDef.value;
    }
    return mult;
}

export function getAcademySpiritSynergyMult(game: GameRuntime): number {
    const state = getAcademyCoursesState(game);
    let highRankCount = 0;
    for (const id of ACADEMY_COURSE_IDS) {
        if (id === 'founder') continue;
        if (state[id].rank >= 3) highRankCount += 1;
    }
    if (highRankCount < 2) return 0;
    const founder = getAcademyCourseEntry(game, 'founder');
    if (founder.rank < 5) return 0.25;
    return 0.5;
}

export function isAcademyAdvancedHubUnlocked(game: GameRuntime): boolean {
    if (typeof game.hasBadge === 'function' && game.hasBadge('maitre_paldea')) return true;
    if (game.badges?.maitre_paldea) return true;
    const state = getAcademyCoursesState(game);
    let spent = 0;
    for (const id of ACADEMY_COURSE_IDS) {
        spent += state[id].creditsSpent;
    }
    return spent >= ACADEMY_ADVANCED_HUB_CREDITS_SPENT;
}

export function migrateAcademyCoursesFromBadges(game: GameRuntime): void {
    getAcademyCoursesState(game);
    if (game.badges?.maitre_paldea || game.currentRegion === 'paldea') {
        onPaldeaRegionVisited(game);
    }
    for (const [badgeKey, courseId] of Object.entries(PALDEA_BADGE_TO_ACADEMY_COURSE)) {
        const has = typeof game.hasBadge === 'function'
            ? game.hasBadge(badgeKey)
            : !!game.badges?.[badgeKey];
        if (has) unlockAcademyCourse(game, courseId, 1);
    }
}

export function countAcademyCoursesAtRank(game: GameRuntime, minRank: number): number {
    const state = getAcademyCoursesState(game);
    let count = 0;
    for (const id of ACADEMY_COURSE_IDS) {
        if (id === 'founder') continue;
        if (state[id].rank >= minRank) count += 1;
    }
    return count;
}
